<template><div class="workflow-page"><header class="page-head"><div><span class="eyebrow">采叶 / 采收端</span><h1>采收批次</h1><p>把地块、叶位和鲜重记录成可追踪批次。</p></div><button class="primary" @click="showForm=!showForm">{{showForm?'收起':'新建批次'}}</button></header><form v-if="showForm" class="form-panel" @submit.prevent="create"><div class="form-grid"><label>批次号<input v-model="form.batch_no" placeholder="如 2026-H-001" required></label><label>地块<select v-model="form.parcel_id" required><option value="">请选择</option><option v-for="p in parcels" :value="p.id" :key="p.id">{{p.name}}</option></select></label><label>采收日期<input v-model="form.harvest_date" type="date" required></label><label>鲜烟叶重量（kg）<input v-model="form.fresh_weight" type="number" min="0" step="0.01" required></label><label>叶位<input v-model="form.leaf_position" placeholder="中部叶、上部叶"></label><label>生长阶段<select v-model="form.growth_stage"><option>成熟期</option><option>旺长期</option></select></label></div><label>备注<textarea v-model="form.notes" rows="3"></textarea></label><button class="primary" :disabled="busy">{{busy?'保存中...':'保存批次'}}</button><p v-if="message" class="message">{{message}}</p></form><section class="table-panel"><div class="panel-title"><strong>批次记录</strong><span>{{items.length}} 条</span></div><div v-if="!items.length" class="empty">暂无采收批次，请从真实采收记录开始。</div><div v-for="item in items" :key="item.id" class="batch-row"><div><strong>{{item.batch_no}}</strong><small>{{item.parcel__name}} · {{item.harvest_date}} · {{item.fresh_weight}} kg</small></div><span class="status">{{statusText[item.status]||item.status}}</span></div></section></div></template>
<script>
import axios from 'axios'; import {API_BASE} from '@/config/api';
export default{data:()=>({parcels:[],items:[],showForm:false,busy:false,message:'',form:{batch_no:'',parcel_id:'',harvest_date:new Date().toISOString().slice(0,10),fresh_weight:'',leaf_position:'',growth_stage:'成熟期',notes:''},statusText:{pending:'待入库',stored:'已入库',sent_to_curing:'已送烘烤'}}),async mounted(){await Promise.all([this.loadParcels(),this.load()]);},methods:{async loadParcels(){const uid=localStorage.getItem('userId');const r=await axios.get(`${API_BASE}/user/${uid}/fields/list/`);this.parcels=r.data.data||[];},async load(){const r=await axios.get(`${API_BASE}/harvest/batches/`);this.items=r.data.data?.items||[];},async create(){this.busy=true;this.message='';try{await axios.post(`${API_BASE}/harvest/batches/`,this.form);this.message='批次已保存';this.form.batch_no='';this.form.fresh_weight='';this.showForm=false;await this.load();}catch(e){this.message=e.response?.data?.msg||'保存失败，请检查输入';}finally{this.busy=false;}}}};
</script>
<style scoped>
.workflow-page{max-width:1060px;margin:auto}.page-head{display:flex;justify-content:space-between;align-items:flex-start;padding:18px 2px}.eyebrow{font-size:12px;color:#27865a;font-weight:700}.page-head h1{margin:6px 0;color:#1b583c;font-size:26px}.page-head p{margin:0;color:#789081;font-size:13px}.primary{border:0;background:#1f8758;color:#fff;border-radius:7px;padding:10px 15px}.form-panel,.table-panel{background:#fff;border:1px solid #dcebe1;border-radius:12px;padding:17px;margin-bottom:14px}.form-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}label{display:block;color:#41634f;font-size:12px;font-weight:600;margin-bottom:13px}input,select,textarea{display:block;width:100%;box-sizing:border-box;margin-top:6px;padding:10px;border:1px solid #cfe2d5;border-radius:7px;font:inherit;font-weight:400}.panel-title{display:flex;justify-content:space-between;color:#285f43}.panel-title span,.batch-row small{color:#81988a;font-size:12px}.empty{padding:35px 5px;text-align:center;color:#82998d;font-size:13px}.batch-row{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #edf3ee;padding:13px 0}.batch-row small{display:block;margin-top:4px}.status{padding:4px 8px;border-radius:20px;background:#e8f5ed;color:#278258;font-size:12px}.message{color:#2b8258;font-size:13px}@media(max-width:650px){.form-grid{grid-template-columns:1fr 1fr}}@media(max-width:430px){.page-head{gap:10px}.page-head h1{font-size:22px}.form-grid{grid-template-columns:1fr}}
</style>
